#include <vector>
#include <algorithm>
#include <unordered_map>
#include <unordered_set>

class Solution {
    static int digitSum(int x) {
        int s = 0;
        while (x > 0) {
            s += x % 10;
            x /= 10;
        }
        return s;
    }

public:
    int minSwaps(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> sorted_nums = nums;
        std::sort(sorted_nums.begin(), sorted_nums.end(), [](int a, int b) {
            int da = digitSum(a), db = digitSum(b);
            if (da != db) return da < db;
            return a < b;
        });

        std::unordered_map<int, int> num_to_idx;
        for (int i = 0; i < n; ++i) {
            num_to_idx[sorted_nums[i]] = i;
        }

        std::vector<bool> seen(n, false);
        int ans = 0;

        for (int i = 0; i < n; ++i) {
            if (seen[i] || num_to_idx[nums[i]] == i) continue;
            int cycle_sz = 0;
            int j = i;
            while (!seen[j]) {
                seen[j] = true;
                j = num_to_idx[nums[j]];
                cycle_sz++;
            }
            if (cycle_sz > 1) {
                ans += cycle_sz - 1;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    private int digitSum(int x) {
        int s = 0;
        while (x > 0) {
            s += x % 10;
            x /= 10;
        }
        return s;
    }

    public int minSwaps(int[] nums) {
        int n = nums.length;
        Integer[] sortedNums = new Integer[n];
        for (int i = 0; i < n; ++i) sortedNums[i] = nums[i];

        Arrays.sort(sortedNums, (a, b) -> {
            int da = digitSum(a), db = digitSum(b);
            if (da != db) return Integer.compare(da, db);
            return Integer.compare(a, b);
        });

        Map<Integer, Integer> numToIdx = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            numToIdx.put(sortedNums[i], i);
        }

        boolean[] seen = new boolean[n];
        int ans = 0;

        for (int i = 0; i < n; ++i) {
            if (seen[i] || numToIdx.get(nums[i]) == i) continue;
            int cycleSz = 0;
            int j = i;
            while (!seen[j]) {
                seen[j] = true;
                j = numToIdx.get(nums[j]);
                cycleSz++;
            }
            if (cycleSz > 1) {
                ans += cycleSz - 1;
            }
        }
        return ans;
    }
}

