var minSwaps = function(nums) {
    function digitSum(x) {
        let s = 0;
        while (x > 0) {
            s += x % 10;
            x = Math.floor(x / 10);
        }
        return s;
    }

    const sortedNums = [...nums].sort((a, b) => {
        const da = digitSum(a), db = digitSum(b);
        if (da !== db) return da - db;
        return a - b;
    });

    const numToIdx = new Map();
    sortedNums.forEach((v, i) => numToIdx.set(v, i));

    const seen = new Set();
    let ans = 0;

    for (let i = 0; i < nums.length; ++i) {
        if (seen.has(i) || numToIdx.get(nums[i]) === i) continue;
        let cycleSz = 0;
        let j = i;
        while (!seen.has(j)) {
            seen.add(j);
            j = numToIdx.get(nums[j]);
            cycleSz++;
        }
        if (cycleSz > 1) {
            ans += cycleSz - 1;
        }
    }
    return ans;
};
